def solve_sequence(x1, x2):
    """
    Calculates the sequence x_i based on the recurrence relation and returns the length n.
    The relation is: x_{i+1} = (x_i^2 + 1) / (x_{i-1} + 1) - 1
    """
    if x1 <= 0 or x2 <= 0: return 0
    sequence = [x1, x2]
    n = 2

    while True:
        x_prev2 = sequence[-2]
        x_prev1 = sequence[-1]

        numerator = x_prev1**2 + 1
        denominator = x_prev2 + 1

        if denominator <= 0:
            return n # Should not happen if inputs are positive

        if numerator % denominator != 0:
            return n # Sequence terminates (not an integer)

        x_next = (numerator // denominator) - 1

        if x_next <= 0:
            return n # Sequence terminates (not positive)

        sequence.append(x_next)
        n += 1

        if n > 10: # Limit search to length 10 for efficiency
            return n

