def search_n4():
    max_n4_found = False
    found_sequences = []

    # Iterate through starting pairs (x1, x2)
    for x1 in range(1, 21):
        for x2 in range(1, 21):
            # Step 1: Calculate x3
            numerator_x3 = x2**2 + 1
            denominator_x3 = x1 + 1

            if numerator_x3 % denominator_x3 == 0:
                x3 = (numerator_x3 // denominator_x3) - 1

                # Check if x3 is a positive integer
                if x3 >= 1:
                    # Step 2: Calculate x4
                    numerator_x4 = x3**2 + 1
                    denominator_x4 = x2 + 1

                    if numerator_x4 % denominator_x4 == 0:
                        x4 = (numerator_x4 // denominator_x4) - 1

                        # Check if x4 is a positive integer
                        if x4 >= 1:
                            max_n4_found = True
                            found_sequences.append((x1, x2, x3, x4))
                            # Since we only need to know if one exists, we can stop early if desired, 
                            # but we'll run the full loop to be thorough.

    if max_n4_found:
        print(f"Found sequences of length n=4.")
        print(f"Total sequences found: {len(found_sequences)}")
        # Print the first few results
        for seq in found_sequences[:5]:
            print(f"Example sequence: x1={seq[0]}, x2={seq[1]}, x3={seq[2]}, x4={seq[3]}")
    else:
        print("No sequences of length n=4 were found in the search range 1 <= x1, x2 <= 20.")

search_n4()
